var i=[{title:`Jak rozwijają się umiejętności`,text:`Na początku musisz myśleć o podstawowych pozycjach i kolejności: gdzie postawić stopy, jak poruszać biodrami, jak prowadzić łokcie. Z praktyką ruchy stają się bardziej powtarzalne i wymagają mniej uwagi. Na zaawansowanym poziomie możesz dostosowywać wyuczony ruch do różnych obciążeń i sytuacji, co wymaga czegoś więcej niż zapamiętania jednego idealnie wyglądającego powtórzenia.`},{title:`Jakość praktyki`,text:`Częste, dokładne powtórzenia z obciążeniem, które kontrolujesz, dają więcej przydatnej nauki niż rzadkie, chaotyczne próby na maksa. Zacznij od wersji ćwiczenia, którą kontrolujesz. Postępuj przez zakres, opór, wymagania równowagi lub szybkość dopiero wtedy, gdy obecna wersja jest powtarzalna.`},{title:`Wskazówki zewnętrzne i wewnętrzne`,text:`Wskazówka wewnętrzna może brzmieć „napnij pośladki”, a zewnętrzna „odpchnij podłogę”. Różne wskazówki działają u różnych osób i w różnych ruchach. Używaj jednej krótkiej wskazówki naraz, bo kilkanaście instrukcji dotyczących części ciała w jednym powtórzeniu to za dużo do opanowania.`},{title:`Informacja zwrotna`,text:`Nagranie z pomocnego kąta może pokazać nierówną głębokość, problemy z równowagą lub niechciany ruch tułowia, choć kąty kamery potrafią wprowadzać w błąd. Lustro może pomóc wyczuć pozycję, ale nie musisz w nie ciągle patrzeć. Trener jest wart zachodu przy nieznanych, złożonych ćwiczeniach lub problemach z techniką, które ciągle wracają.`},{title:`Zmęczenie zmienia naukę`,text:`Duże zmęczenie może obniżać precyzję, więc nowe lub wysoce umiejętnościowe ćwiczenia rób blisko początku treningu. Później w sesji lepiej pasują znane i prostsze ćwiczenia. Kończ serię, gdy technika staje się niekontrolowana, i nie traktuj każdego załamania jako produktywnego wysiłku.`},{title:`Korzystanie z TrainUp`,text:`Strona każdego ćwiczenia w zakładce Ćwiczenia zawiera zdjęcia, kroki i notatki o technice, a plan wybiera ćwiczenia pasujące do Twojego poziomu i koordynacji. Zapisuj powtórzenia, które faktycznie wykonałeś, i używaj notatek do treningu, by zapisać, czy były kontrolowane.`}];var o=[{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Zasady progresji ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var n={sections:i,sources:o};export{n as default,i as sections,o as sources};